{
  "failure_story": "Через шесть месяцев после внедрения более точного фильтра и белого списка отток платящих клиентов вырос до 7%, доход упал, количество ложных блокировок не сократилось, а стоимость поддержки увеличилась; партнерские соглашения не успели подписать, бюджетные ограничения привели к недоработкам, и проект был признан нецелесообразным.",
  "causes": [
    {
      "cause": "Белый список не успел пополняться из‑за длительных переговоров, поэтому большинство звонков курьеров и банков продолжали блокироваться, вызывая отток клиентов.",
      "likelihood": "likely",
      "early_signal": "За месяц в белый список добавилось менее 5 новых организаций, при росте запросов на добавление более чем на 30%.",
      "mitigation": "Ускорить юридический процесс, подготовить шаблоны соглашений, предусмотреть временный fallback‑механизм с ручной верификацией."
    },
    {
      "cause": "Повышенная точность фильтра привела к слишком строгим правилам, увеличив количество ложных блокировок, особенно для курьеров, что отразилось на оттоке и конверсии.",
      "likelihood": "very_likely",
      "early_signal": "Рост жалоб на блокировку выше 10% от общего числа звонков и снижение конверсии пробного периода ниже 20% в течение двух недель.",
      "mitigation": "Провести A/B‑тестирование порогов, добавить возможность ручного пересмотра блокировок и быстро откатывать изменения при росте жалоб."
    },
    {
      "cause": "Сокращение бюджета на доработки привело к недоработке интеграции с партнёрами и появлению багов, вызывающих падения системы и рост нагрузки на техподдержку.",
      "likelihood": "likely",
      "early_signal": "Увеличение количества тикетов в техподдержке более чем на 15% и задержки в выпуске обновлений более 2 недель.",
      "mitigation": "Пересмотреть приоритеты, привлечь внешних подрядчиков, создать резервный фонд для критических задач."
    },
    {
      "cause": "Сохранённая цена 99 ₽ стала восприниматься как слишком высокая после ухудшения качества сервиса, усилив отток.",
      "likelihood": "roughly_even",
      "early_signal": "Более 30% всех новых отзывов за месяц касаются цены.",
      "mitigation": "Запустить ценовой эксперимент с временными скидками или гибкой тарифной моделью, собрать обратную связь."
    },
    {
      "cause": "Откат онбординга к прежнему варианту без учёта изменений в UI вызвал путаницу у новых пользователей, снизив конверсию пробного периода.",
      "likelihood": "unlikely",
      "early_signal": "Конверсия пробного периода падает ниже 22% в течение двух последовательных месяцев.",
      "mitigation": "Провести UX‑тестирование, добавить обучающие подсказки и видео, собрать метрики поведения новых пользователей."
    }
  ],
  "kill_criteria": [
    "Отток платящих клиентов превышает 6% в квартальном измерении.",
    "Доля жалоб на ложные блокировки превышает 15% от всех звонков.",
    "Конверсия пробного периода падает ниже 20% два месяца подряд.",
    "Белый список не пополняется более чем 2 новыми организациями в месяц в течение трёх месяцев.",
    "Задержка релизов из‑за бюджетных ограничений превышает 4 недели.",
    "Общий доход от продукта снижается более чем на 10% за квартал."
  ]
}

